  var LAST = 'titanpulse';
  var SVGNS = 'http://www.w3.org/2000/svg';

  function hexRgb(hex) {
    var m = /^#?([0-9a-f]{6})$/i.exec(String(hex || ''));
    if (!m) return '255,255,255';
    var n = parseInt(m[1], 16);
    return ((n >> 16) & 255) + ',' + ((n >> 8) & 255) + ',' + (n & 255);
  }

  /** Variance (log) d'un tick : même calcul que orolado_feed_tick_var (feed_lib.php). */
  function tickVar(m) {
    var v = m.sigma * m.sigma;
    var hold = Number(m.hold) || 0;
    var wideP = Number(m.wideP) || 0;
    if (hold > 0 || wideP > 0) {
      var k = Number(m.wideK) || 1;
      v *= (1.0 - hold) * (1.0 - wideP + wideP * k * k);
    }
    if ((Number(m.jumpP) || 0) > 0) {
      var a = Number(m.jumpMin), b = Number(m.jumpMax);
      v += m.jumpP * (a * a + a * b + b * b) / 3.0;
    }
    return v;
  }

  /** Variance « ordinaire » (pics comptés à 15 %) : hauteur du cadre du graphique (affichage seulement). */
  function spanVar(m) {
    var v = tickVar({ sigma: m.sigma, hold: m.hold, wideP: m.wideP, wideK: m.wideK, jumpP: 0 });
    if ((Number(m.jumpP) || 0) > 0) {
      var a = Number(m.jumpMin), b = Number(m.jumpMax);
      v += 0.15 * m.jumpP * (a * a + a * b + b * b) / 3.0;
    }
    return v;
  }

  var LINE_KINDS = { step: 1, mountain: 1, neon: 1, ribbon: 1, stars: 1, baseline: 1, thread: 1, current: 1, coins: 1, comet: 1, ohlc: 1, diamonds: 1, dashes: 1, zigzag: 1, dotline: 1, rings: 1, arcs: 1 };
  // 2026-10-19 (propriétaire : « chaque monde a SON dessin ») : 45 dessins uniques, tous posés comme une courbe
  // (un point au centre de chaque seconde) — js/chart.js, drawExt2.
  ['pixel', 'nightsky', 'clouds', 'crescent', 'tomb', 'chevrons', 'coinstack', 'hammers', 'petrify', 'chain', 'sundisc',
    'tombstones', 'claws', 'constellation', 'lava', 'grass', 'glitch', 'aurora', 'bats', 'mandala', 'banners', 'crowns', 'eyes',
    'gears', 'mosaic', 'tide', 'dunes', 'fans', 'spirals', 'drops', 'notes', 'cubes', 'hearts', 'bubbles', 'speed', 'hive',
    'sparkles', 'scales', 'wave', 'feathers', 'jaws', 'halftone', 'ankh', 'ink', 'flames'].forEach(function (kd) { LINE_KINDS[kd] = 1; });
  var CANDLE_KINDS = { classic: 1, hollow: 1, capsule: 1, bricks: 1, led: 1, arrows: 1, spark: 1, glass: 1 };
  var STYLED_KINDS = { pearls: 1, embers: 1, crystals: 1, bars: 1 };

  /** Fiche marché (même forme que les 10 de js/config.js). */
  function assetOf(e) {
    var L = e.look || {};
    var a = {
      id: e.id,
      name: e.name,
      short: e.name,
      tag: e.tag || '',
      basePrice: e.base,
      tickNoise: 0.4,
      tickMs: 32,
      ticksPerCandle: 8,
      payoutMin: 1.9,
      payoutMax: 1.9,
      accent: e.accent,
      accentDim: hexRgb(e.accent),
      feed: e.id,
      ext: true,
      fair: e.fair,
      fairVar: tickVar(e.model),
      spanVar: spanVar(e.model),
      zoomIdx: L.zoom,
      // Tempo (affichage seulement, le modèle de prix ne change pas) : hot = cadre plus serré (mouvements plus
      // grands à l'écran, plus vif), calm = cadre plus large (courbe posée, majestueuse).
      tempo: L.tempo || 'normal',
      planet: e.planet
    };
    var kind = L.kind || '';
    if (LINE_KINDS[kind]) {
      // Courbe : dessin propre au marché (js/chart.js, drawExt).
      a.chart = 'line';
      a.lineColor = L.line || L.up || e.accent;
      a.lineWidth = L.width || 2.6;
      a.xkind = kind;
      a.xdraw = L;
    } else if (CANDLE_KINDS[kind]) {
      a.chart = 'candle';
      a.plotTheme = 'darkPro';
      a.candlePal = { up: L.up || e.accent, dn: L.dn || '#FF3B5C' };
      a.xkind = kind;
      a.xdraw = L;
    } else if (STYLED_KINDS[kind]) {
      // Dessins des marchés d'origine (perles, braises, cristaux, barres), avec LES couleurs du marché.
      a.chart = 'candle';
      a.plotTheme = 'darkPro';
      a.candlePal = { up: L.up || e.accent, dn: L.dn || '#FF3B5C' };
      a.styled = kind;
    } else {
      a.chart = 'candle';
      a.plotTheme = 'darkPro';
      a.candlePal = { up: L.up || e.accent, dn: L.dn || '#FF3B5C' };
      a.xkind = 'classic';
      a.xdraw = L;
    }
    return a;
  }

  /* —— Logos : un symbole par marché, dessiné ici (SVG maison), posé dans son globe —— */
  function star(cx, cy, r1, r2, n) {
    var p = '', i;
    for (i = 0; i < n * 2; i++) {
      var r = i % 2 ? r2 : r1;
      var a = -Math.PI / 2 + i * Math.PI / n;
      p += (i ? 'L' : 'M') + (cx + r * Math.cos(a)).toFixed(2) + ' ' + (cy + r * Math.sin(a)).toFixed(2);
    }
    return p + 'Z';
  }
  function rays(cx, cy, r1, r2, n) {
    var p = '', i;
    for (i = 0; i < n; i++) {
      var a = i * 2 * Math.PI / n;
      p += 'M' + (cx + r1 * Math.cos(a)).toFixed(2) + ' ' + (cy + r1 * Math.sin(a)).toFixed(2) +
        'L' + (cx + r2 * Math.cos(a)).toFixed(2) + ' ' + (cy + r2 * Math.sin(a)).toFixed(2);
    }
    return p;
  }
