  function bindBarScroll(bar) {
    try {
      bar.addEventListener('wheel', function (ev) {
        if (bar.scrollWidth <= bar.clientWidth + 4) return;
        if (Math.abs(ev.deltaY) <= Math.abs(ev.deltaX)) return;
        bar.scrollLeft += ev.deltaY;
        ev.preventDefault();
      }, { passive: false });
    } catch (eW) { /* ignore */ }
    if (!(root.matchMedia && root.matchMedia('(hover:hover) and (pointer:fine)').matches)) return;
    var wrap = bar.parentNode;
    if (!wrap) return;
    function arrow(dir) {
      var a = document.createElement('button');
      a.type = 'button';
      a.className = 'mk-arrow mk-arrow-' + dir;
      a.setAttribute('aria-label', dir === 'l' ? 'Previous' : 'Next');
      a.innerHTML = dir === 'l' ? '&#9664;' : '&#9654;';
      a.addEventListener('click', function (ev) {
        ev.preventDefault();
        ev.stopPropagation();
        var step = Math.max(160, bar.clientWidth * 0.8) * (dir === 'l' ? -1 : 1);
        try { bar.scrollBy({ left: step, behavior: 'smooth' }); } catch (eS) { bar.scrollLeft += step; }
      });
      return a;
    }
    var l = arrow('l');
    var r = arrow('r');
    document.body.appendChild(l);
    document.body.appendChild(r);
    function place() {
      var rc = bar.getBoundingClientRect();
      var horiz = rc.width > rc.height * 1.5;
      var on = horiz && rc.width > 0 && bar.scrollWidth > bar.clientWidth + 4 && rc.bottom > 0;
      l.style.display = r.style.display = on ? 'flex' : 'none';
      if (!on) return;
      var top = (rc.top + Math.min(rc.height, 60) / 2 - 14) + 'px';
      l.style.top = r.style.top = top;
      l.style.left = (rc.left + 2) + 'px';
      r.style.left = (rc.right - 30) + 'px';
      l.classList.toggle('dim', bar.scrollLeft <= 2);
      r.classList.toggle('dim', bar.scrollLeft + bar.clientWidth >= bar.scrollWidth - 2);
    }
    bar.addEventListener('scroll', place, { passive: true });
    root.addEventListener('resize', place);
    root.addEventListener('scroll', place, { passive: true });
    setInterval(place, 700);
    place();
  }

